    "codeExample": "#include <stdio.h>\n\nenum DataType {\n    DATA_INT = 1,\n    DATA_FLOAT = 2,\n    DATA_CHAR = 3\n};\n\nstruct DynamicValue {\n    enum DataType type;\n    union {\n        int i;\n        float f;\n        char c;\n    } payload;\n};\n\nvoid printValue(const struct DynamicValue *v) {\n    switch (v->type) {\n        case DATA_INT:\n            printf(\"[INTEGER] Value: %d\\n\", v->payload.i);\n            break;\n        case DATA_FLOAT:\n            printf(\"[FLOAT] Value: %.2f\\n\", v->payload.f);\n            break;\n        case DATA_CHAR:\n            printf(\"[CHAR] Value: '%c'\\n\", v->payload.c);\n            break;\n        default:\n            printf(\"[UNKNOWN] Invalid type\\n\");\n            break;\n    }\n}\n\nint main(void) {\n    struct DynamicValue v1;\n    v1.type = DATA_INT;\n    v1.payload.i = 2048;\n\n    struct DynamicValue v2;\n    v2.type = DATA_FLOAT;\n    v2.payload.f = 3.14159f;\n\n    struct DynamicValue v3;\n    v3.type = DATA_CHAR;\n    v3.payload.c = 'Z';\n\n    printValue(&v1);\n    printValue(&v2);\n    printValue(&v3);\n    return 0;\n}",
