    "codeExample": "#include <stdio.h>\n#include <stdlib.h>\n\nstruct DNode {\n    int data;\n    struct DNode *prev;\n    struct DNode *next;\n};\n\nstruct DNode* insertDHead(struct DNode *head, int val) {\n    struct DNode *newNode = (struct DNode *)malloc(sizeof(struct DNode));\n    newNode->data = val;\n    newNode->prev = NULL;\n    newNode->next = head;\n\n    if (head != NULL) {\n        head->prev = newNode;\n    }\n    return newNode;\n}\n\nvoid printForwardAndBackward(struct DNode *head) {\n    struct DNode *curr = head;\n    struct DNode *tail = NULL;\n\n    printf(\"Forward:  \");\n    while (curr != NULL) {\n        printf(\"%d \", curr->data);\n        if (curr->next == NULL) tail = curr; // Capture tail\n        curr = curr->next;\n    }\n    printf(\"\\n\");\n\n    printf(\"Backward: \");\n    curr = tail;\n    while (curr != NULL) {\n        printf(\"%d \", curr->data);\n        curr = curr->prev;\n    }\n    printf(\"\\n\");\n}\n\nvoid freeDList(struct DNode *head) {\n    struct DNode *curr = head;\n    while (curr != NULL) {\n        struct DNode *temp = curr;\n        curr = curr->next;\n        free(temp);\n    }\n}\n\nint main(void) {\n    struct DNode *head = NULL;\n    head = insertDHead(head, 30);\n    head = insertDHead(head, 20);\n    head = insertDHead(head, 10);\n\n    printForwardAndBackward(head);\n    freeDList(head);\n    return 0;\n}",
