        "code_snippet": "#include <stdio.h>\n#include <stdlib.h>\n#include <stdbool.h>\n\nstruct TreeNode {\n    int data;\n    struct TreeNode *left;\n    struct TreeNode *right;\n};\n\nstruct TreeNode* insert(struct TreeNode *root, int val) {\n    if (root == NULL) {\n        struct TreeNode *n = (struct TreeNode *)malloc(sizeof(struct TreeNode));\n        n->data = val;\n        n->left = n->right = NULL;\n        return n;\n    }\n    if (val < root->data) {\n        root->left = insert(root->left, val);\n    } else if (val > root->data) {\n        root->right = insert(root->right, val);\n    }\n    return root;\n}\n\nbool search(struct TreeNode *root, int key) {\n    if (root == NULL) return false;\n    if (root->data == key) return true;\n    if (key < root->data) return search(root->left, key);\n    return search(root->right, key);\n}\n\nvoid inorder(struct TreeNode *root) {\n    if (root == NULL) return;\n    inorder(root->left);\n    printf(\"%d \", root->data);\n    inorder(root->right);\n}\n\nvoid freeTree(struct TreeNode *root) {\n    if (root == NULL) return;\n    freeTree(root->left);   // Postorder cleanup\n    freeTree(root->right);\n    free(root);\n}\n\nint main(void) {\n    struct TreeNode *root = NULL;\n    int keys[] = {50, 30, 70, 20, 40, 60, 80};\n    for (int i = 0; i < 7; i++) {\n        root = insert(root, keys[i]);\n    }\n\n    printf(\"BST Inorder (Sorted): \");\n    inorder(root);\n    printf(\"\\n\");\n\n    printf(\"Search for 40: %s\\n\", search(root, 40) ? \"FOUND\" : \"NOT FOUND\");\n    printf(\"Search for 99: %s\\n\", search(root, 99) ? \"FOUND\" : \"NOT FOUND\");\n\n    freeTree(root);\n    printf(\"BST memory successfully freed.\\n\");\n    return 0;\n}",
